package android.os;import java.util.*;public class Handler {static class Entry {Handler owner;Runnable r;long due,order;Entry(Handler h,Runnable r,long d,long o){owner=h;this.r=r;due=d;order=o;}}public static PriorityQueue<Entry> queue=new PriorityQueue<>((a,b)->a.due!=b.due?Long.compare(a.due,b.due):Long.compare(a.order,b.order));static long next;public Handler(){}public Handler(Looper l){}public boolean post(Runnable r){return postDelayed(r,0);}public boolean postDelayed(Runnable r,long delay){queue.add(new Entry(this,r,SystemClock.now+delay,next++));return true;}public boolean postAtTime(Runnable r,long time){queue.add(new Entry(this,r,time,next++));return true;}public void removeCallbacks(Runnable r){queue.removeIf(e->e.owner==this&&e.r==r);}public void removeCallbacksAndMessages(Object t){queue.removeIf(e->e.owner==this);}public void handleMessage(Message m){}public static void runFor(long ms){long end=SystemClock.now+ms;int count=0;while(!queue.isEmpty()&&queue.peek().due<=end){if(++count>100000)throw new AssertionError("unbounded handler loop");Entry e=queue.poll();SystemClock.now=e.due;e.r.run();}SystemClock.now=end;}public static void reset(){queue.clear();SystemClock.now=1000;next=0;}}